class Solution:
    def findRLEArray(self, encoded1: List[List[int]], encoded2: List[List[int]]) -> List[List[int]]:
        nums1, nums2 = [], []
        for v, f in encoded1:
            nums1.extend([v] * f)
        for v, f in encoded2:
            nums2.extend([v] * f)
        res = []
        for a, b in zip(nums1, nums2):
            p = a * b
            if res and res[-1][0] == p:
                res[-1][1] += 1
            else:
                res.append([p, 1])
        return res

