class Solution {
public:
    vector<vector<int>> findRLEArray(vector<vector<int>>& encoded1, vector<vector<int>>& encoded2) {
        vector<long long> nums1, nums2;
        for (auto& seg : encoded1)
            nums1.insert(nums1.end(), (long long)seg[0], seg[1]);
        for (auto& seg : encoded2)
            nums2.insert(nums2.end(), (long long)seg[0], seg[1]);
        vector<vector<int>> res;
        for (size_t i = 0; i < nums1.size(); ++i) {
            int p = nums1[i] * nums2[i];
            if (!res.empty() && res.back()[0] == p) res.back()[1]++;
            else res.push_back({p, 1});
        }
        return res;
    }
};

