class Solution {
    public List<List<Integer>> findRLEArray(int[][] encoded1, int[][] encoded2) {
        List<Integer> nums1 = new ArrayList<>(), nums2 = new ArrayList<>();
        for (int[] seg : encoded1)
            for (int t = 0; t < seg[1]; t++) nums1.add(seg[0]);
        for (int[] seg : encoded2)
            for (int t = 0; t < seg[1]; t++) nums2.add(seg[0]);
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < nums1.size(); i++) {
            int p = nums1.get(i) * nums2.get(i);
            if (!res.isEmpty() && res.get(res.size() - 1).get(0) == p)
                res.get(res.size() - 1).set(1, res.get(res.size() - 1).get(1) + 1);
            else
                res.add(new ArrayList<>(Arrays.asList(p, 1)));
        }
        return res;
    }
}

