class Solution:
    def findRLEArray(self, encoded1: List[List[int]], encoded2: List[List[int]]) -> List[List[int]]:
        res = []
        i = j = 0
        fi, fj = encoded1[0][1], encoded2[0][1]
        while i < len(encoded1):
            take = min(fi, fj)
            prod = encoded1[i][0] * encoded2[j][0]
            if res and res[-1][0] == prod:
                res[-1][1] += take
            else:
                res.append([prod, take])
            fi -= take
            fj -= take
            if fi == 0:
                i += 1
                if i < len(encoded1):
                    fi = encoded1[i][1]
            if fj == 0:
                j += 1
                if j < len(encoded2):
                    fj = encoded2[j][1]
        return res

